def merge_all(a, tmp, l, r):
    """归并排序统计全部逆序对（k=1）"""
    if r - l <= 1:
        return 0
    m = (l + r) // 2
    cnt = merge_all(a, tmp, l, m) + merge_all(a, tmp, m, r)
    i, j, p = l, m, l
    while i < m or j < r:
        if j == r or (i < m and a[i] <= a[j]):
            tmp[p] = a[i]
            i += 1
        else:
            cnt += (m - i)
            tmp[p] = a[j]
            j += 1
        p += 1
    a[l:r] = tmp[l:r]
    return cnt

class BIT:
