        self.n = n
        self.t = [0] * (n + 1)
    def update(self, i, v=1):
        while i <= self.n:
            self.t[i] += v
            i += i & -i
    def query(self, i):
        s = 0
        while i > 0:
            s += self.t[i]
            i -= i & -i
        return s

