    n, k = data[0], data[1]
    a = data[2:]

    if k >= 3:
        print(0)
        return

    if k == 1:
        tmp = [0] * n
        print(merge_all(a, tmp, 0, n))
    else:
        # k == 2：免费交换同奇偶，只计算奇偶不同的逆序对
        bit_even = BIT(n)
        bit_odd = BIT(n)
        for x in a:
            if x & 1:
